```go
package main

import (
    "errors"
    "fmt"
)

type ValidationError struct {
    Field  string
    Reason string
}

func (e *ValidationError) Error() string {
    return e.Field + ": " + e.Reason
}

func validateName(name string) error {
    if name == "" {
        return &ValidationError{Field: "name", Reason: "must not be empty"}
    }
    return nil
}

func main() {
    err := validateName("")
    var validation *ValidationError
    fmt.Println(err)
    fmt.Println(errors.As(err, &validation), validation.Field)
}
```
The program prints the readable message and then `true name`, showing that one value supports both display and structured inspection.

```go
package main

import "fmt"

type ParseError struct{ Message string }

func (e *ParseError) Error() string {
    if e == nil {
        return "<nil ParseError>"
    }
    return e.Message
}

func wrong() error {
    var err *ParseError
    return err
}

func right() error { return nil }

func main() {
    fmt.Println(wrong() == nil)
    fmt.Println(right() == nil)
}
```
The output is `false` and then `true`. A nil-safe method changes printing behavior, but not the interface comparison.

```go
package main

import (
    "errors"
    "fmt"
)

type SyntaxError struct {
    Line int
    Text string
}

func (e *SyntaxError) Error() string {
    return fmt.Sprintf("line %d: %s", e.Line, e.Text)
}

func parse(input string) error {
    if input != "ok" {
        return &SyntaxError{Line: 1, Text: "expected ok"}
    }
    return nil
}

func main() {
    err := parse("bad")
    var syntax *SyntaxError
    if errors.As(err, &syntax) {
        fmt.Println(syntax.Line)
    }
}
```
The function exposes only `error`, while the caller still prints line `1` after a successful structured match.
